/* Token Radar — dark radar-room theme. No network: every pixel is local. */
:root {
  --bg: #0a1120;
  --panel: #101c33;
  --panel-2: #152441;
  --line: #22375e;
  --ink: #e8eefb;
  --muted: #93a5c4;
  --faint: #64748f;
  --accent: #a3e635;
  --accent-dim: #65a30d;
  --gold: #fbbf24;
  --red: #fb7185;
  --green: #4ade80;
  --radius: 12px;
  --font: "Segoe UI", system-ui, -apple-system, Roboto, "Helvetica Neue", Arial, sans-serif;
  --mono: ui-monospace, "SF Mono", "Cascadia Code", Consolas, monospace;
}
* { box-sizing: border-box; }
html { color-scheme: dark; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--font);
  font-size: 15px;
  line-height: 1.5;
}
body::before {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(700px 320px at 85% -10%, rgba(163, 230, 53, 0.10), transparent 60%),
    radial-gradient(600px 300px at -10% 0%, rgba(59, 130, 246, 0.14), transparent 60%);
}
a { color: var(--accent); }
.skip {
  position: absolute;
  left: -999px;
  top: 0;
  background: var(--accent);
  color: #0a1120;
  padding: 8px 14px;
  border-radius: 0 0 8px 0;
  font-weight: 700;
  z-index: 50;
}
.skip:focus { left: 0; }
.shell { position: relative; max-width: 1180px; margin: 0 auto; padding: 20px 18px 48px; }
.num { font-variant-numeric: tabular-nums; white-space: nowrap; }
.sub { color: var(--muted); font-size: 13px; }

/* header */
.top {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 6px 2px 18px;
  border-bottom: 1px solid var(--line);
}
.brand { display: flex; align-items: center; gap: 12px; }
.mark {
  width: 38px; height: 38px; border-radius: 50%;
  border: 2px solid var(--accent);
  background:
    radial-gradient(circle at 50% 50%, var(--accent) 0 3px, transparent 4px),
    repeating-radial-gradient(circle at 50% 50%, transparent 0 8px, rgba(163, 230, 53, 0.35) 8px 9px);
  flex: none;
}
.brand-name { font-size: 22px; font-weight: 800; letter-spacing: 0.04em; }
.brand-name small {
  display: block;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--accent);
}
.top-meta { display: flex; flex-wrap: wrap; gap: 8px 18px; color: var(--muted); font-size: 13px; }
.top-meta b { color: var(--ink); font-weight: 600; }

/* lede + stats */
.lede { padding: 22px 2px 6px; }
.lede h1 { margin: 0 0 8px; font-size: 27px; line-height: 1.2; max-width: 760px; }
.lede h1 em { font-style: normal; color: var(--accent); }
.lede p { margin: 0; max-width: 780px; color: var(--muted); }
.facts {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
  margin: 18px 0 4px;
}
.fact {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 14px 16px;
}
.fact span { display: block; color: var(--muted); font-size: 12px; text-transform: uppercase; letter-spacing: 0.08em; }
.fact b { display: block; font-size: 22px; margin-top: 4px; }
.fact small { color: var(--faint); font-size: 12px; }

/* controls */
.controls {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  align-items: end;
  margin: 18px 0 14px;
  padding: 14px;
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: var(--radius);
}
.field { display: flex; flex-direction: column; gap: 5px; min-width: 0; }
.field label, .field .sub { font-size: 12px; color: var(--muted); text-transform: uppercase; letter-spacing: 0.08em; }
.field.grow { flex: 1 1 260px; }
input[type="search"], select {
  background: var(--bg);
  color: var(--ink);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 9px 11px;
  font: inherit;
  font-size: 14px;
}
input[type="search"]:focus, select:focus { outline: 2px solid var(--accent); outline-offset: 1px; }
.tabs { display: flex; gap: 6px; }
.tabs button {
  background: var(--bg);
  color: var(--muted);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 9px 14px;
  font: inherit;
  font-size: 14px;
  cursor: pointer;
}
.tabs button[aria-pressed="true"] { background: var(--accent); border-color: var(--accent); color: #0a1120; font-weight: 700; }
.count { margin-left: auto; align-self: center; color: var(--muted); font-size: 13px; }

/* table */
.panel {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
}
.table-wrap { overflow-x: auto; }
table { width: 100%; border-collapse: collapse; font-size: 14px; }
caption { text-align: left; padding: 14px 16px 10px; color: var(--muted); }
thead th {
  text-align: left;
  padding: 10px 12px;
  border-bottom: 1px solid var(--line);
  color: var(--muted);
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  white-space: nowrap;
}
thead th button {
  background: none; border: 0; padding: 0;
  color: inherit; font: inherit; cursor: pointer;
  text-transform: inherit; letter-spacing: inherit;
}
thead th button:hover { color: var(--accent); }
tbody td { padding: 11px 12px; border-bottom: 1px solid rgba(34, 55, 94, 0.6); vertical-align: middle; }
tbody tr { cursor: pointer; }
tbody tr:hover, tbody tr:focus-visible { background: var(--panel-2); outline: none; }
tbody tr:last-child td { border-bottom: 0; }
tbody tr[data-selected="true"] { background: rgba(163, 230, 53, 0.07); box-shadow: inset 3px 0 0 var(--accent); }
.name b { display: block; font-size: 15px; }
.pos { color: var(--green); }
.neg { color: var(--red); }
.status {
  display: inline-block;
  padding: 3px 9px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 700;
  background: rgba(163, 230, 53, 0.14);
  color: var(--accent);
  white-space: nowrap;
}
.status.live { background: rgba(251, 191, 36, 0.14); color: var(--gold); }
.implied .bar {
  height: 5px;
  background: var(--line);
  border-radius: 3px;
  margin-bottom: 5px;
  min-width: 90px;
}
.implied .bar i {
  display: block;
  height: 5px;
  border-radius: 3px;
  background: linear-gradient(90deg, var(--accent-dim), var(--accent));
}
.empty { padding: 40px 24px; text-align: center; }
.empty h2 { margin: 0 0 6px; }
.empty p { color: var(--muted); margin: 0 0 16px; }
.button {
  background: var(--accent);
  color: #0a1120;
  border: 0;
  border-radius: 8px;
  padding: 10px 16px;
  font: inherit;
  font-weight: 700;
  cursor: pointer;
}
.button.ghost { background: transparent; color: var(--accent); border: 1px solid var(--accent); }

/* model + sandbox */
.model { margin-top: 16px; padding: 20px 22px; }
.model h2 { margin: 0 0 6px; font-size: 19px; }
.model p { color: var(--muted); margin: 0 0 12px; max-width: 820px; }
.formula {
  font-family: var(--mono);
  font-size: 13px;
  background: var(--bg);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 12px 14px;
  overflow-x: auto;
  white-space: nowrap;
  margin-bottom: 14px;
}
.sandbox {
  border-top: 1px solid var(--line);
  padding-top: 14px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px 28px;
}
.sandbox label { display: block; font-size: 13px; color: var(--muted); margin-bottom: 4px; }
.sandbox label b { color: var(--ink); }
.sandbox input[type="range"] { width: 100%; accent-color: var(--accent); }
.sandbox .note { grid-column: 1 / -1; font-size: 13px; }
.sandbox .note b { color: var(--accent); }

/* detail dialog */
dialog.detail {
  background: var(--panel);
  color: var(--ink);
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 0;
  width: min(680px, 94vw);
  max-height: 88vh;
  overflow: auto;
  box-shadow: 0 24px 70px rgba(0, 0, 0, 0.6);
}
dialog.detail::backdrop { background: rgba(4, 8, 18, 0.72); }
.detail-head {
  display: flex;
  justify-content: space-between;
  align-items: start;
  gap: 16px;
  padding: 20px 22px 0;
}
.detail-head h2 { margin: 4px 0 2px; font-size: 24px; }
.detail-head .sub { margin: 0; }
.close {
  background: var(--bg);
  color: var(--ink);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 8px 13px;
  font: inherit;
  cursor: pointer;
  flex: none;
}
.detail-section { padding: 16px 22px 20px; border-top: 1px solid var(--line); margin-top: 16px; }
.detail-section h3 { margin: 0 0 12px; font-size: 16px; }
.equation { display: grid; grid-template-columns: 1fr 1fr; gap: 8px 20px; }
.equation div {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  padding: 9px 12px;
  background: var(--bg);
  border: 1px solid var(--line);
  border-radius: 8px;
}
.equation span { color: var(--muted); font-size: 13px; }
.equation .total { grid-column: 1 / -1; border-color: var(--accent-dim); }
.equation .total b { color: var(--accent); }
.steps { margin: 0; padding-left: 22px; }
.steps li { margin-bottom: 12px; }
.steps li b { display: block; font-weight: 600; }
.steps .cost { color: var(--muted); font-size: 13px; }
.foot { padding: 22px 2px 0; color: var(--faint); font-size: 13px; }
.foot p { margin: 0 0 6px; }

@media (max-width: 760px) {
  .facts { grid-template-columns: 1fr 1fr; }
  .sandbox { grid-template-columns: 1fr; }
  .equation { grid-template-columns: 1fr; }
  .lede h1 { font-size: 22px; }
  .count { margin-left: 0; }
}
